var returnDay = (arg) => {
  $date = new Date(arg);
  return getTheDay($date);
}
function getTheDay(date){
  $a = date.getDay();
  if($a == 1){
    $theDay = "Monday";
  }else if($a == 2){
    $theDay = "Tuesday";
  }else if($a == 3){
    $theDay = "Wednesday";
  }else if($a == 4){
    $theDay = "Thursday";
  }else if($a == 5){
    $theDay = "Friday";
  }else if($a == 6){
    $theDay = "Saturday";
  }else if($a == 0){
    $theDay = "Sunday";
  }
  return $theDay;
}
